import{_ as a,o as e,c as l,ae as i}from"./chunks/framework.Dh1jimFm.js";const g=JSON.parse('{"title":"Batch Translation","description":"","frontmatter":{},"headers":[],"relativePath":"ai-translation/batch-translation.md","filePath":"ai-translation/batch-translation.md"}'),r={name:"ai-translation/batch-translation.md"};function o(s,t,n,h,d,c){return e(),l("div",null,t[0]||(t[0]=[i('<h1 id="batch-translation" tabindex="-1">Batch Translation <a class="header-anchor" href="#batch-translation" aria-label="Permalink to &quot;Batch Translation&quot;">​</a></h1><p>Translate multiple segments at once with AI.</p><h2 id="starting-batch-translation" tabindex="-1">Starting Batch Translation <a class="header-anchor" href="#starting-batch-translation" aria-label="Permalink to &quot;Starting Batch Translation&quot;">​</a></h2><ol><li><p><strong>Select segments</strong> to translate:</p><ul><li>Click first segment, Shift+click last for a range</li><li>Or use <strong>Edit → Select All</strong> (<code>Ctrl+A</code>)</li></ul></li><li><p><strong>Start batch</strong>:</p><ul><li>Press <code>Ctrl+Shift+T</code></li><li>Or go to <strong>Edit → Batch Translate</strong></li></ul></li></ol><h2 id="batch-dialog-options" tabindex="-1">Batch Dialog Options <a class="header-anchor" href="#batch-dialog-options" aria-label="Permalink to &quot;Batch Dialog Options&quot;">​</a></h2><h3 id="provider-selection" tabindex="-1">Provider Selection <a class="header-anchor" href="#provider-selection" aria-label="Permalink to &quot;Provider Selection&quot;">​</a></h3><p>Choose your LLM provider:</p><ul><li>OpenAI (GPT-4o, GPT-4-turbo)</li><li>Anthropic (Claude 3.5, Claude 3)</li><li>Google (Gemini Pro)</li><li>Ollama (local models)</li></ul><h3 id="translation-mode" tabindex="-1">Translation Mode <a class="header-anchor" href="#translation-mode" aria-label="Permalink to &quot;Translation Mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>LLM Only</strong></td><td>Use AI for all segments</td></tr><tr><td><strong>TM First</strong></td><td>Use TM matches above threshold, AI for rest</td></tr><tr><td><strong>TM + Context</strong></td><td>Include TM matches as context for AI</td></tr></tbody></table><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><ul><li><strong>Skip confirmed segments</strong>: Don&#39;t re-translate ✅ segments</li><li><strong>Include context</strong>: Send surrounding segments for better quality</li><li><strong>Retry until complete</strong>: Auto-retry segments that return empty</li></ul><h2 id="progress-tracking" tabindex="-1">Progress Tracking <a class="header-anchor" href="#progress-tracking" aria-label="Permalink to &quot;Progress Tracking&quot;">​</a></h2><p>During translation:</p><ul><li>Progress bar shows completion</li><li>Per-segment status updates</li><li>Can cancel anytime</li></ul><h2 id="retry-feature" tabindex="-1">Retry Feature <a class="header-anchor" href="#retry-feature" aria-label="Permalink to &quot;Retry Feature&quot;">​</a></h2><p>Enable <strong>&quot;🔄 Retry until all segments are translated&quot;</strong> to:</p><ul><li>Automatically detect empty translations</li><li>Retry failed segments (up to 5 passes)</li><li>Ensure all segments get translated</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><h3 id="optimal-batch-size" tabindex="-1">Optimal Batch Size <a class="header-anchor" href="#optimal-batch-size" aria-label="Permalink to &quot;Optimal Batch Size&quot;">​</a></h3><ul><li>50-100 segments per batch works well</li><li>Very large batches may timeout</li><li>Split by page if needed</li></ul><h3 id="quality-vs-speed" tabindex="-1">Quality vs Speed <a class="header-anchor" href="#quality-vs-speed" aria-label="Permalink to &quot;Quality vs Speed&quot;">​</a></h3><ul><li>GPT-4o: Good balance of speed and quality</li><li>Claude 3 Opus: Highest quality, slower</li><li>GPT-3.5/Gemini: Fastest, lower cost</li></ul><h3 id="post-edit-strategy" tabindex="-1">Post-Edit Strategy <a class="header-anchor" href="#post-edit-strategy" aria-label="Permalink to &quot;Post-Edit Strategy&quot;">​</a></h3><p>After batch translation:</p><ol><li>Review each segment</li><li>Fix any obvious errors</li><li>Confirm with <code>Ctrl+Enter</code></li></ol><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./overview.html">AI Translation Overview</a></li><li><a href="./prompts.html">Creating Prompts</a></li><li><a href="./single-segment.html">Single Segment Translation</a></li></ul>',29)]))}const p=a(r,[["render",o]]);export{g as __pageData,p as default};
